code='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        marks = [(c, grid[r][c]) for c in range(cols) if grid[r][c] != background]
        for (left, color), (right, next_color) in zip(marks, marks[1:]):
            if color == next_color:
                for c in range(left + 1, right):
                    out[r][c] = 3
    for c in range(cols):
        marks = [(r, grid[r][c]) for r in range(rows) if grid[r][c] != background]
        for (top, color), (bottom, next_color) in zip(marks, marks[1:]):
            if color == next_color:
                for r in range(top + 1, bottom):
                    out[r][c] = 3
    return out
'''
